const body = $json.body || $json;
const ALLOWED_TYPES = [
  'PUMP_MASTER', 'MECHANICAL_SEAL_MASTER', 'SEAL_STOCK', 'SEAL_INTERCHANGE',
  'PUMP_COMPATIBILITY', 'INSTALLATION_HISTORY', 'MAINTENANCE_HISTORY',
  'ENGINEER_MASTER', 'CUSTOMER_MASTER', 'VENDOR_MASTER', 'BILL_OF_MATERIAL'
];

if (!body.mapping_profile_id) {
  throw new Error('mapping_profile_id is required');
}

if (body.workbook_type !== undefined && !ALLOWED_TYPES.includes(body.workbook_type)) {
  throw new Error('workbook_type must be one of: ' + ALLOWED_TYPES.join(', '));
}

const updatable = [
  'profile_name', 'workbook_type', 'customer', 'description', 'status'
];

const fields = {};
for (const key of updatable) {
  if (body[key] !== undefined) {
    fields[key] = body[key];
  }
}

if (Object.keys(fields).length === 0) {
  throw new Error('at least one updatable field is required');
}

return [{
  json: {
    mapping_profile_id: body.mapping_profile_id,
    fields
  }
}];

const { mapping_profile_id, fields } = $json;
const keys = Object.keys(fields);

const setClauses = keys.map((key, idx) => `${key} = $${idx + 1}`);
setClauses.push('updated_at = NOW()');

const params = keys.map((key) => fields[key]);
params.push(mapping_profile_id);

const query = `UPDATE mapping_profile SET ${setClauses.join(', ')} WHERE mapping_profile_id = $${params.length} RETURNING *;`;

return [{
  json: {
    mapping_profile_id,
    query,
    params
  }
}];

const row = $input.first()?.json;

if (!row || !row.mapping_profile_id) {
  return [{
    json: {
      statusCode: 404,
      success: false,
      message: 'Mapping profile not found',
      data: null
    }
  }];
}

return [{
  json: {
    statusCode: 200,
    success: true,
    message: 'Mapping profile updated successfully',
    data: row
  }
}];
